-- `assembly_member` definition

CREATE TABLE `assembly_member` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sch_unit_cd` varchar(10) DEFAULT NULL,
  `row_num` int(11) DEFAULT NULL,
  `emp_no` varchar(20) DEFAULT NULL,
  `mona_cd` varchar(20) DEFAULT NULL,
  `hg_nm` varchar(20) DEFAULT NULL,
  `hj_nm` varchar(20) DEFAULT NULL,
  `eng_nm` varchar(20) DEFAULT NULL,
  `age` int(11) DEFAULT NULL,
  `sex_gbn_nm` varchar(20) DEFAULT NULL,
  `dept_img_url` varchar(200) DEFAULT NULL,
  `poly_cd` varchar(20) DEFAULT NULL,
  `poly_nm` varchar(20) DEFAULT NULL,
  `orig_nm` varchar(20) DEFAULT NULL,
  `ele_gbn_nm` varchar(20) DEFAULT NULL,
  `reele_gbn_nm` varchar(20) DEFAULT NULL,
  `unit_cd` varchar(20) DEFAULT NULL,
  `units` varchar(200) DEFAULT NULL,
  `cmit_nm` varchar(20) DEFAULT NULL,
  `cmits` varchar(500) DEFAULT NULL,
  `tel_no` varchar(20) DEFAULT NULL,
  `e_mail` varchar(20) DEFAULT NULL,
  `homepage` varchar(200) DEFAULT NULL,
  `staff` varchar(20) DEFAULT NULL,
  `secretary` varchar(20) DEFAULT NULL,
  `secretary2` varchar(20) DEFAULT NULL,
  `bth_date` varchar(20) DEFAULT NULL,
  `unit_nm` varchar(20) DEFAULT NULL,
  `link_url` varchar(200) DEFAULT NULL,
  `open_na_id` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

